def sanitize_text(text: str) -> str:
    if not text:
        return ""
    t = text.replace("\u201c", '"').replace("\u201d", '"')
    t = t.replace("\u2018", "'").replace("\u2019", "'")
    t = t.replace("\u2013", "-").replace("\u2014", "-")
    t = t.replace("\u2026", "...")
    t = t.encode("ascii", "ignore").decode("ascii")
    return t


