            job.status = JobStatus.FAILED
            job.error = str(e)
            job.updated_at = datetime.now().isoformat()

    async def identify_knowledge_gaps(self, sources: List[Source]) -> List[str]:
        if len(sources) < 5:
            return ["alapvető információk", "definíciók", "háttér adatok"]
        topics = set()
        for source in sources[:20]:
            words = source.title.split()
            for w in words:
                if len(w) > 4:
                    topics.add(w.lower())
        base_topics = ["történeti háttér", "nemzetközi kontextus", "jövőbeli kilátások", "kritikai értékelés"]
        res = []
        sel = list(topics)[:3]
        for t in base_topics:
            res.append(f"{t} {' '.join(sel)}")
        return res[:5]

    async def recover_from_error(self, job: JobState, error: Exception):
        job.action_logs.append(ActionLog(timestamp=datetime.now().isoformat(), tool="Recovery System", action="Hiba észlelve, helyreállítás", parameters={"error_type": type(error).__name__}, result_summary=f"Helyreállítás folyamatban: {str(error)[:100]}", confidence=0.5))
        if "API" in str(error):
            await asyncio.sleep(5)
        elif "timeout" in str(error).lower():
            await asyncio.sleep(1)
        last_checkpoint = job_store.load_last_checkpoint(job.job_id)
        if last_checkpoint:
            job.sources = last_checkpoint.sources
            job.action_logs = last_checkpoint.action_logs


class ResearchOrchestrator:
    def __init__(self):
        self.exa = ExaAdapter()
        self.grok = GrokAdapter()
        self.gpt5 = GPT5Adapter()
        self.cerebras = CerebrasAdapter()

    async def route_task(self, task_type: str, complexity: str) -> str:
        if task_type == "critical_reasoning" and complexity == "high":
            return "grok4"
        if task_type in {"synthesis", "code_generation"}:
            return "gpt5"
        if task_type == "quick_verification":
            return "grok4_fast"
        if task_type == "hypothesis_generation":
            return "qwen235b"
        return "gpt_oss_120b"

    async def progressive_exa_search(self, job: JobState, depth_level: int = 3) -> List[Dict[str, Any]]:
        all_sources: List[Dict[str, Any]] = []
        for level in range(depth_level):
            if level == 0:
                queries = [job.prompt]
            elif level == 1:
                queries = await self.generate_sub_questions(job.prompt)
            else:
                queries = await self.identify_knowledge_gaps_from_sources(all_sources)
            tasks = [self.exa.search(query=q, num_results=200) for q in queries[:10]]
            results = await asyncio.gather(*tasks, return_exceptions=True)
            for result in results:
                if isinstance(result, dict):
                    all_sources.extend(result.get("sources", []))
            logger.info(f"Level {level+1}: {len(all_sources)} total sources")
        return all_sources

    async def generate_sub_questions(self, main_question: str) -> List[str]:
        try:
            sub = await self.cerebras.deep_reasoning(question=main_question, context="Kezdeti kérdés-dekompozíció", model="qwen-3-235b-a22b-thinking-2507")
            arr = sub.get("question_breakdown", [main_question])
            return [a for a in arr if isinstance(a, str) and a.strip()][:5] or [main_question]
        except Exception:
            return [main_question]

    async def identify_knowledge_gaps_from_sources(self, sources: List[Dict[str, Any]]) -> List[str]:
        if len(sources) < 10:
            return ["mélyebb elemzés szükséges"]
        titles = [str(s.get("title", "")) for s in sources[:15]]
        combined_titles = " ".join(titles)
        gap_keywords = ["következmények", "okok", "alternatívák", "kritika", "jövőkép"]
        return [f"{kw} {combined_titles[:50]}" for kw in gap_keywords]

    async def update_and_broadcast(self, job: JobState, progress: Optional[float] = None, current_step: Optional[str] = None, status: Optional[JobStatus] = None):
        if progress is not None:
            job.progress = float(progress)
        if current_step is not None:
            job.current_step = str(current_step)
        if status is not None:
            job.status = status
        job.updated_at = datetime.now().isoformat()
        job_store.save_job(job)
        await ws_manager.broadcast(job.job_id, {"type": "status_update", "job_id": job.job_id, "status": job.status.value, "progress": job.progress, "current_step": job.current_step, "action_logs_count": len(job.action_logs), "sources_count": len(job.sources)})

    async def cross_validate_results(self, grok_result: Dict[str, Any], gpt5_result: str) -> str:
        try:
            _ = {"grok_analysis": grok_result, "gpt5_synthesis": gpt5_result[:2000]}
            return await self.gpt5.cross_validate_analysis("Többmodelles keresztvalidáció", [json.dumps(grok_result), gpt5_result])
        except Exception as e:
            logger.error(f"Cross validation error: {str(e)}")
            return f"Keresztvalidáció hiba: {str(e)}"

