        try:
            job.status = JobStatus.RUNNING
            job.current_step = "Kezdeti keresés Exa-val"
            job.progress = 0.1
            action_log = ActionLog(timestamp=datetime.now().isoformat(), tool="Exa AI", action="Széles körű webes keresés", parameters={"query": job.prompt, "num_results": 100}, result_summary="Keresés indítása...", confidence=None)
            job.action_logs.append(action_log)
