            sorted_sources = sorted(unique_sources, key=lambda x: float(x.get("score", 0.0)), reverse=True)[:20]
            for i, src in enumerate(sorted_sources, 1):
                final_report += f"\n{i}. **[{src['title']}]({src['url']})**"
